// Changes: Behaviour of the split divider – limits, keyboard (arrows, Home/End) and the announced value.

import { describe, expect, it } from 'vitest'
import { splitBounds, splitValue, widthForKey } from './splitWidth'

describe('split width', () => {
  it('keeps room for the right column (360px + 16px of gaps)', () => {
    expect(splitBounds(1200)).toEqual({ min: 280, max: 824 })
  })

  it('never lets the maximum fall below the minimum on narrow boxes', () => {
    expect(splitBounds(500)).toEqual({ min: 280, max: 280 })
  })

  it('moves by 20px with arrows and 80px with Shift, clamped to the bounds', () => {
    const b = splitBounds(1200)
    expect(widthForKey('ArrowRight', false, 400, b)).toBe(420)
    expect(widthForKey('ArrowLeft', true, 400, b)).toBe(320)
    expect(widthForKey('ArrowLeft', true, 300, b)).toBe(280)
    expect(widthForKey('ArrowRight', true, 800, b)).toBe(824)
  })

  it('jumps to the minimum with Home and the maximum with End', () => {
    const b = splitBounds(1200)
    expect(widthForKey('Home', false, 400, b)).toBe(280)
    expect(widthForKey('End', false, 400, b)).toBe(824)
  })

  it('ignores other keys, including Enter', () => {
    expect(widthForKey('Enter', false, 400, splitBounds(1200))).toBeUndefined()
    expect(widthForKey('a', false, 400, splitBounds(1200))).toBeUndefined()
  })

  it('reports the value as a percentage of the layout width with readable text', () => {
    expect(splitValue(400, 1200)).toEqual({ now: 33, min: 23, max: 69, text: 'Ľavý stĺpec 33 % šírky (400 px)' })
  })
})
